  `id_periodo` int(11) DEFAULT NULL,
  `id_materia_oficial` int(11) DEFAULT NULL,
  PRIMARY KEY (`id_estandar`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
