INSERT INTO `revision` VALUES (1,'Zuly Camila','Tarjetapresentaci????????????n','Recomiendo que aproveches el espacio de trabajo para que puedas ubicar informaci????????????n de la empresa, ya que aunque el logo se puede visualizar no se encuentra los datos de la empresa','IMG_20190806_112517[1].jpg.jpg','3'),(2,'Zuly Camila','Creatividad','Es agradable ver un los colores del objeto que representan al logo y su concepto,pero te recomiendo dejar solo los componentes de la imagen adjunta con el fin de no saturar de informaci????????????n al cliente ','IMG_20190806_123139[1].jpg.jpg','4,5'),(3,'Zuly Camila','Logo ','El logo representa el ???????????rea de salud pero creo que la cruz puede sobrar ya que 3 componentes junto al coraz????????????n son evidentemente contundentes en el mensaje de la empresa','boton[1].jpg.jpg','4.5'),(4,'Zuly Camila','Afiche','El afiche tiene una dimensi????????????n adecuada, como sugerencia yo recomendar???????????a quitar la cruz de la parte superior del afiche','IMG_20190806_124734[1].jpg.jpg','4'),(5,'Zuly Camila','CD','No hay presentaci????????????n de cd','','1'),(6,'Zuly Camila','Calendario','No hay presentaci????????????n del calendario','','1'),(7,'n/a29353','Logo ','Es un excelente logo que representa la marca ciclistica','IMG_20190806_130618[1].jpg.jpg','5'),(8,'n/a29353','CD','Jesus recuerda siempre usar una interfaz impresa en el cd que permite ver un producto de mayor calidad ','IMG_20190806_130558[1].jpg.jpg','5'),(9,'n/a29353','Afiche','La presentaci????????????n esta muy bien pero te recomiendo aprovechar los espacios para mostrar la informaci????????????n de la empresa','IMG_20190806_130618[1].jpg.jpg','5'),(10,'Nelly Mercedes','Logo ','Con el paso del tiempo es necesario ir evolucionando y mejorando la propuesta del logo tipo actual','IMG_20190806_134357_1[1].jpg.jpg','4'),(11,'Nelly Mercedes','Tarjetapresentaci????????????n','Tener cuidado con los bordes del logo de whatsapp en la tarjeta de presentaci????????????n','IMG_20190806_134416[1].jpg.jpg','4.5'),(12,'Nelly Mercedes','Afiche','El afiche tiene una buena distribuci????????????n pero ser???????????a bueno aprovechar los espacios para complementar con informaci????????????n como contacto de la empresa ','IMG_20190806_134229[1].jpg.jpg','4'),(13,'Nelly Mercedes','carnet','Recomiendo tener en cuenta el espacio entre los textos con el fin de mantener una proporci????????????n en el carnet','IMG_20190806_134435[1].jpg.jpg','4'),(14,'Nelly Mercedes','CD','Verificar que el logo no se cruce con el centro del cd ','IMG_20190806_134357[1].jpg.jpg','4.5'),(15,'Nelly Mercedes','Calendario','En el calendario en forma de triangulo deberia presentar informaci????????????n de contacto como la otra opci????????????n de calendario presentada ','IMG_20190806_134337[1].jpg.jpg','4.5'),(16,'Nelly Mercedes','Creatividad','La propuesta de camiseta es una forma de publicidad muy optima , si se desea t???????????mbien se puede aprovechar el espacio en ella.','','4'),(17,'Fabiola Jesus','Logo ','El logo presenta una representaci????????????n pertinente al contexto de la empresa junto a su paleta de colores','','4.5'),(18,'Fabiola Jesus','Afiche','Tener en cuenta un grupo de fuentes de texto alternativas para obtener un mayor impacto en la lectura del usuario','IMG_20190806_141306[1].jpg.jpg','4.5'),(19,'Nelly Mercedes','Tarjetapresentaci????????????n','Tener cuidado y dejar un margen entre los bordes de la tarjeta, ya que al cortar se puede modificar parte del texto','IMG_20190806_141520[1].jpg.jpg','4.5'),(20,'Fabiola Jesus','CD','Presentar un orden proporcional en el contorno del cd para que exista armonia','IMG_20190806_141439[1].jpg.jpg','4.5'),(21,'Fabiola Jesus','Creatividad','Es agradable y la distribuci????????????n se encuentra mucho m???????????s estable que en la presentaci????????????n del cd','IMG_20190806_142324[1].jpg.jpg','5'),(22,'Fabiola Jesus','Calendario','Se puede complementar con la informaci????????????n de la empresa para mayor reconocimiento del cliente','','4.5'),(23,'Magali','Tarjetapresentaci????????????n','Es necesario recortar tarjeta de presentaci????????????n ','IMG_20190806_143047[1].jpg.jpg','3.5'),(24,'Magali','Logo ','.','','3.8'),(25,'Magali','Afiche','Tener cuidado con el lugar de impresi????????????n ya que el afiche presenta una linea que es por falta de alineaci????????????n de los cabezales de la impresora','IMG_20190806_143117[1].jpg.jpg','4'),(26,'Magali','carnet','Verificar la alineaci????????????n del texto presente en el carnet y la distribuci????????????n de los elementos ','IMG_20190806_143152[1].jpg.jpg','3.8'),(27,'Magali','Creatividad','En cuanto al lapicero es una excelente idea pero ser???????????a ideal complementar con informaci????????????n de contacto','IMG_20190806_143217[1].jpg.jpg','4.5'),(28,'Magali','Calendario','Las letras en el logo del calendario se encuentran desbordadas ','IMG_20190806_143132[1].jpg.jpg','3.5'),(29,'yuri ','Creatividad','La idea del lapicero es importante pero los datos de contacto en el lapicero permiten dar un plus al objeto','','4.5'),(30,'yuri','CD','De igual formaque en el lapicero en el cd podemos complementar con informaci????????????n b???????????sica de la empresa como correo el???????????ctronico.','','4.5'),(31,'yuri','Tarjetapresentaci????????????n','Es necesario recortar tarjeta de presentaci????????????n	','','3.5'),(32,'yuri','carnet','Se recomienda que el calendario se en espa????????????ol por el contexto Colombiano','','5'),(33,'yuri','Afiche','Se puede aprovechar mucho m???????????s el espacio del afiche ya que una gran proporci????????????n se encuentra vac???????????o','','4'),(34,'yuri','Logo ','La idea es muy buena, pero creo que se le puede dar una integraci????????????n que puede ser m???????????s interesante y llamativo para el usuario, le recomiendo que en el futuro el logo evolucione ','','3.5');
